  /* ---------- recording ---------- */
  function stopRec(discard){
    if(mr){try{if(discard)mr.__discard=1;mr.stop()}catch(e){}}
    recOn=false;rec.classList.remove('rec');
  }
  on(rec,'click',function(){
    if(recOn){stopRec(false);rec.textContent='🎙 อัดเสียงฉัน';return}
    if(!navigator.mediaDevices){rec.textContent='เครื่องนี้อัดเสียงไม่ได้';return}
    navigator.mediaDevices.getUserMedia({audio:{echoCancellation:true,noiseSuppression:true}}).then(function(stream){
      chunks=[];mr=new MediaRecorder(stream);
      mr.ondataavailable=function(e){if(e.data)chunks.push(e.data)};
      mr.onstop=function(){
        stream.getTracks().forEach(function(x){x.stop()});
        if(mr.__discard)return;
        recBlob=new Blob(chunks,{type:mr.mimeType||'audio/webm'});
        var u=URL.createObjectURL(recBlob);rp.src=u;dl.href=u;
        dl.download='moonlight-karaoke-'+cur.id+(recBlob.type.indexOf('mp4')===-1?'.webm':'.m4a');
        recBox.style.display='flex';rec.textContent='🎙 อัดใหม่';
      };
      mr.start();recOn=true;rec.classList.add('rec');rec.textContent='⏺ กำลังอัด (แตะเพื่อหยุด)';
      if(au.paused)playNow();
    }).catch(function(){rec.textContent='ต้องอนุญาตไมค์ก่อนนะคะ'});
  });
