  function chips(opts,multi,max){
    var box=h('div','mck-chips'),sel=[];
    opts.forEach(function(o){
      var b=h('button','mck-chip',o);
      on(b,'click',function(){
        var i=sel.indexOf(o);
        if(i!==-1){sel.splice(i,1);b.classList.remove('on');return}
        if(!multi){sel=[o];Array.prototype.slice.call(box.children).forEach(function(c){c.classList.remove('on')});b.classList.add('on');return}
        if(sel.length===max){var first=sel.shift();Array.prototype.slice.call(box.children).forEach(function(c){if(c.textContent===first)c.classList.remove('on')})}
        sel.push(o);b.classList.add('on');
      });
      box.appendChild(b);
    });
    return {el:box,get:function(){return sel.slice()}};
  }
